56	
57	    /** Dedicated audit trail logger; carries a line for each successful owner create. */
58	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
59	
60	    /** Notification logger; carries the welcome notification enqueued for each successful create. */
61	    private static final org.slf4j.Logger NOTIFY = org.slf4j.LoggerFactory.getLogger("NOTIFY");
62	
63	    /**
64	     * Process-wide monotonically increasing sequence stamped onto each structured owner-created
65	     * audit event, so events can be totally ordered across creates.
66	     */
67	    private static final java.util.concurrent.atomic.AtomicInteger AUDIT_SEQ =
68	        new java.util.concurrent.atomic.AtomicInteger(0);
69	
70	    /** Serializes the immutable structured audit events to JSON. */
71	    private static final tools.jackson.databind.ObjectMapper AUDIT_MAPPER =
72	        new tools.jackson.databind.json.JsonMapper();
73	
74	    /**
75	     * Immutable structured audit event emitted (as JSON, on the {@code AUDIT} logger) for each
76	     * successful owner create. {@code schemaVersion} is the audit-event schema version (2 since the
77	     * version-2 owner identity release), {@code seq} is the process-wide {@link #AUDIT_SEQ} counter,
78	     * {@code memberId} carries the owner's primary identifier (the version-2 unified memberId) and
79	     * {@code ownerSegment} carries the owner's marketing segment recomputed from the version-2
80	     * identity. The component order matches the JSON field order.
81	     */
82	    private record OwnerCreatedEvent(int schemaVersion, int seq, Integer ownerId, String memberId,
83	        Integer membershipLevel, String ownerSegment, String event) {
84	    }
