140	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
141	     *  separated by '@', none of which contain whitespace or a second '@'. */
142	    private static final java.util.regex.Pattern EMAIL_PATTERN =
143	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
144	
145	    /** Disposable email domains that are not accepted as an owner's email. */
146	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
147	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
148	
149	    /**
150	     * Normalize the optional email: absent stays absent; when present it must be syntactically
151	     * valid and is lower-cased. Returns {@code false} if present but invalid, including when its
152	     * domain is on the disposable-domain blocklist.
153	     */
154	    private boolean normalizeEmail(Owner owner) {
155	        String email = owner.getEmail();
156	        if (email == null || email.isEmpty()) {
157	            owner.setEmail(null);
158	            return true;
159	        }
160	        if (!EMAIL_PATTERN.matcher(email).matches()) {
161	            return false;
162	        }
163	        email = email.toLowerCase(java.util.Locale.ROOT);
164	        String domain = email.substring(email.indexOf('@') + 1);
165	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
166	            return false;
167	        }
168	        owner.setEmail(email);
169	        return true;
170	    }
171	
172	    /**
173	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
174	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
175	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
176	     *
177	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
178	     *         a valid E.164 number.
179	     */
180	    private static String toE164(String raw) {
181	        if (raw == null) {
182	            return null;
183	        }
184	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
185	        String digits;
186	        if (cleaned.startsWith("+")) {
187	            digits = cleaned.substring(1);
188	        } else {
189	            if (cleaned.startsWith("0")) {
190	                cleaned = cleaned.substring(1);
191	            }
192	            digits = "61" + cleaned;
193	        }
194	        if (!digits.matches("\\d{8,15}")) {
195	            return null;
196	        }
197	        return "+" + digits;
198	    }
199	
200	    /**
201	     * Validate the national-number length of a canonical E.164 string against its country code:
202	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Numbers carrying any
203	     * other country code are not length-checked here and are accepted. Expects the '+'-prefixed digit
204	     * string produced by {@link #toE164}.
205	     *
206	     * @return {@code true} when the national-number length is correct for the country code.
207	     */
208	    private static boolean hasValidNationalLength(String e164) {
209	        String digits = e164.substring(1);
210	        if (digits.startsWith("61")) {
211	            return digits.length() - 2 == 9;
212	        }
213	        if (digits.startsWith("1")) {
214	            return digits.length() - 1 == 10;
215	        }
216	        return true;
217	    }
218	
219	    /**
220	     * The version-2 region code embedded inside the identifiers: the fixed {@code 'V2'} version tag
221	     * mixed with the region code derived from the owner's postcode (NSW/VIC/QLD, or {@code UNKNOWN}
222	     * when the postcode is absent or in no known range), e.g. {@code V2NSW} or {@code V2UNKNOWN}.
223	     * Because it always carries the {@code 'V2'} prefix it never equals a version-1 (plain) region,
224	     * so every identifier derived from it changes and no version-1 value is produced again. This is
225	     * only the region code used <em>inside</em> the identifiers; the user-facing {@code locality},
226	     * {@code timezone} and owner-segment region stay the plain region code (see {@link OwnerMapper}).
227	     */
228	    private String identityRegion(Owner owner) {
229	        String region = ownerMapper.regionFromPostcode(owner);
230	        if (region == null) {
231	            region = "UNKNOWN";
232	        }
233	        return Owner.IDENTITY_VERSION_TAG + region;
234	    }
235	
236	    /**
237	     * Build the unified member id {@code <REGION><FY><HASH8><CHK>}: REGION is the version-2 region
238	     * code ({@link #identityRegion(Owner)} — the {@code 'V2'} tag mixed with the postcode-derived
239	     * region, e.g. {@code V2NSW} or {@code V2UNKNOWN}); FY is the two-digit fiscal year of the owner's
240	     * (business-day-adjusted) registrationDate; HASH8 is the first 8 upper-case hex characters of
241	     * SHA-256 over the concatenation of the owner's normalized (E.164) telephone and last name; and
242	     * CHK is a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>} (e.g.
243	     * {@code V2NSW273F9A0C177}). No sequence numbers are used, so the base id is a pure function of
244	     * the owner's region, fiscal year and region-and-hash identity. When that base id collides with an
245	     * existing owner's memberId, {@code -<n>} is appended with the smallest {@code n} of 2 or more that
246	     * makes it unique, returning the de-duplicated id.
247	     */
248	    private String memberIdFor(Owner owner) {
249	        String region = identityRegion(owner);
250	        String fy = String.format("%02d", ownerMapper.fiscalYearOf(owner.getRegistrationDate()) % 100);
251	        String core = region + fy + hash8(owner.getTelephone(), owner.getLastName());
252	        String base = core + luhn(core);
253	
254	        java.util.Set<String> existingIds = new java.util.HashSet<>();
255	        for (Owner existing : this.clinicService.findAllOwners()) {
256	            String id = existing.getMemberId();
257	            if (id != null) {
258	                existingIds.add(id);
259	            }
260	        }
261	        if (!existingIds.contains(base)) {
262	            return base;
263	        }
264	        for (int n = 2; ; n++) {
265	            String candidate = base + "-" + n;
266	            if (!existingIds.contains(candidate)) {
267	                return candidate;
268	            }
269	        }
270	    }
271	
272	    /**
273	     * A single Luhn check digit (0-9) over the digits contained in {@code value}; non-digit characters
274	     * are ignored.
275	     */
276	    private static int luhn(String value) {
277	        int sum = 0;
278	        boolean dbl = true;
279	        for (int i = value.length() - 1; i >= 0; i--) {
280	            char c = value.charAt(i);
281	            if (c < '0' || c > '9') {
282	                continue;
283	            }
284	            int d = c - '0';
285	            if (dbl) {
286	                d *= 2;
287	                if (d > 9) {
288	                    d -= 9;
289	                }
290	            }
291	            sum += d;
292	            dbl = !dbl;
293	        }
294	        return (10 - (sum % 10)) % 10;
295	    }
296	
297	    /**
298	     * First 8 upper-case hex characters (the first 4 bytes) of SHA-256 over
299	     * {@code normalizedTelephone + lastName}, treating a {@code null} component as empty.
300	     */
301	    private static String hash8(String normalizedTelephone, String lastName) {
302	        String input = (normalizedTelephone == null ? "" : normalizedTelephone)
303	            + (lastName == null ? "" : lastName);
304	        try {
305	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
306	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
307	            StringBuilder sb = new StringBuilder(8);
308	            for (int i = 0; i < 4; i++) {
309	                sb.append(String.format("%02X", digest[i]));
310	            }
311	            return sb.toString();
312	        }
313	        catch (java.security.NoSuchAlgorithmException e) {
314	            throw new IllegalStateException(e);
315	        }
316	    }
317	
318	    /** Common street-type abbreviations expanded during address normalization. */
319	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
320	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
321	
322	    /**
323	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
324	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
325	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
326	     */
327	    private static String normalizeAddress(String value) {
328	        if (value == null) {
329	            return "";
330	        }
331	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
332	        if (collapsed.isEmpty()) {
333	            return "";
334	        }
335	        String[] tokens = collapsed.split(" ");
336	        StringBuilder sb = new StringBuilder(collapsed.length());
337	        for (int i = 0; i < tokens.length; i++) {
338	            if (i > 0) {
339	                sb.append(' ');
340	            }
341	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
342	        }
343	        return sb.toString();
344	    }
345	
346	    /**
347	     * Resolve and normalize the owner's postal address, preferring the structured form.
348	     *
349	     * <p>When a non-blank {@code addressLine1} is supplied the structured form is used: it, and the
350	     * optional {@code addressLine2}, are normalized in place and the composed address is the
351	     * normalized addressLine1 with a single space and the normalized addressLine2 appended when
352	     * addressLine2 is present. Otherwise the flat {@code address} input is normalized. Returns
353	     * {@code null} when neither form yields a non-empty address, so the caller can reject the
354	     * request.
355	     */
356	    private String composeAddress(Owner owner) {
357	        String line1 = owner.getAddressLine1();
358	        if (line1 != null && !line1.isBlank()) {
359	            String normalizedLine1 = normalizeAddress(line1);
360	            owner.setAddressLine1(normalizedLine1);
361	            String line2 = owner.getAddressLine2();
362	            if (line2 != null && !line2.isBlank()) {
363	                String normalizedLine2 = normalizeAddress(line2);
364	                owner.setAddressLine2(normalizedLine2);
365	                return normalizedLine1 + " " + normalizedLine2;
366	            }
367	            owner.setAddressLine2(null);
368	            return normalizedLine1.isEmpty() ? null : normalizedLine1;
369	        }
370	        String normalized = normalizeAddress(owner.getAddress());
371	        return normalized.isEmpty() ? null : normalized;
372	    }
373	
374	    /**
375	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
376	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
377	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
378	     */
379	    private static String normalizeForHousehold(String value) {
380	        if (value == null) {
381	            return "";
382	        }
383	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
384	    }
385	
386	    /**
387	     * Return the owners that already share this owner's household, i.e. resolve to the same
388	     * deterministic {@link #householdIdFor(Owner) householdId} (same normalized last name and
389	     * postcode).
390	     */
391	    private List<Owner> householdMembers(Owner owner) {
392	        String householdId = householdIdFor(owner);
393	        List<Owner> members = new java.util.ArrayList<>();
394	        for (Owner existing : this.clinicService.findAllOwners()) {
395	            if (existing.isDeleted()) {
396	                continue;
397	            }
398	            if (householdId.equals(householdIdFor(existing))) {
399	                members.add(existing);
400	            }
401	        }
402	        return members;
403	    }
404	
405	    /**
406	     * Return {@code true} when another owner already shares this owner's household, i.e. resolves to
407	     * the same deterministic {@link #householdIdFor(Owner) householdId}.
408	     */
409	    private boolean sharesHouseholdWithExisting(Owner owner) {
410	        return !householdMembers(owner).isEmpty();
411	    }
412	
413	    /**
414	     * Count the existing owners that share this owner's first name and last name, compared
415	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
416	     */
417	    private int namesakeCount(Owner owner) {
418	        String firstName = owner.getFirstName();
419	        String lastName = owner.getLastName();
420	        int count = 0;
421	        for (Owner existing : this.clinicService.findAllOwners()) {
422	            if (firstName != null && lastName != null
423	                && firstName.equalsIgnoreCase(existing.getFirstName())
424	                && lastName.equalsIgnoreCase(existing.getLastName())) {
425	                count++;
426	            }
427	        }
428	        return count;
429	    }
430	
431	    /**
432	     * A stable, shared household identifier: the first 12 hex characters of SHA-256 over
433	     * {@code 'V2' + '|' + normalizedLastName + '|' + postcode} (an absent postcode contributes an
434	     * empty string). The leading {@code 'V2'} version tag is mixed in so the version-2 value never
435	     * equals the version-1 value, yet the id stays a pure function of the last name and postcode, so
436	     * every owner in the same household still deterministically resolves to the same value.
437	     */
438	    private static String householdIdFor(Owner owner) {
439	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
440	        String key = Owner.IDENTITY_VERSION_TAG + "|" + normalizeForHousehold(owner.getLastName()) + "|" + postcode;
441	        try {
442	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
443	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
444	            StringBuilder sb = new StringBuilder(12);
445	            for (int i = 0; i < 6; i++) {
446	                sb.append(String.format("%02X", digest[i]));
447	            }
448	            return sb.toString();
449	        }
450	        catch (java.security.NoSuchAlgorithmException e) {
451	            throw new IllegalStateException(e);
452	        }
453	    }
454	
455	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
456	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
457	        "NSW", new int[] {2000, 2099},
458	        "VIC", new int[] {3000, 3099},
459	        "QLD", new int[] {4000, 4099});
460	
461	    /**
462	     * Validate the optional postcode. Absent (null/empty) is valid — postcode is optional. When
463	     * present it must be exactly 4 digits; and when the owner's city maps to a known region (via the
464	     * mapper's fixed city-to-region table) it must fall inside that region's inclusive range
465	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
466	     * postcode.
467	     */
468	    private boolean isPostcodeValid(Owner owner) {
469	        String postcode = owner.getPostcode();
470	        if (postcode == null || postcode.isEmpty()) {
471	            return true;
472	        }
473	        if (!postcode.matches("\\d{4}")) {
474	            return false;
475	        }
476	        int[] range = REGION_POSTCODE_RANGES.get(ownerMapper.cityRegion(owner));
477	        if (range == null) {
478	            return true;
479	        }
480	        int value = Integer.parseInt(postcode);
481	        return value >= range[0] && value <= range[1];
482	    }
483	
484	    /**
485	     * Find an existing owner that makes this (already known to be non-hard-duplicate) owner a
486	     * "possible duplicate": one whose last name shares this owner's {@link Owner#soundex(String)
487	     * soundex} and whose postcode matches, yet whose whole {@link Owner#getIdentityKey() identityKey}
488	     * differs (so it is not a hard duplicate). When several match, the one with the smallest id is
489	     * chosen so the result is deterministic. Returns {@code null} when the owner has no postcode or no
490	     * such existing owner exists.
491	     */
492	    private Owner possibleDuplicateOf(Owner owner) {
493	        String lastName = owner.getLastName();
494	        String postcode = owner.getPostcode();
495	        if (lastName == null || postcode == null || postcode.isEmpty()) {
496	            return null;
497	        }
498	        String soundex = Owner.soundex(lastName);
499	        String identityKey = owner.getIdentityKey();
500	        Owner match = null;
501	        for (Owner existing : this.clinicService.findAllOwners()) {
502	            if (soundex.equals(Owner.soundex(existing.getLastName()))
503	                && postcode.equals(existing.getPostcode())
504	                && !identityKey.equals(existing.getIdentityKey())) {
505	                if (match == null || (existing.getId() != null && match.getId() != null
506	                    && existing.getId() < match.getId())) {
507	                    match = existing;
508	                }
509	            }
510	        }
511	        return match;
512	    }
513	
514	    /** Maximum number of owners permitted in a single city. */
515	    private static final int CITY_CAPACITY = 50;
516	
517	    /**
518	     * Number of owners already in a city at or beyond which a capacity warning is flagged (the city
519	     * is approaching the {@link #CITY_CAPACITY} hard limit). A city holding 40-49 owners warns.
520	     */
521	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
522	
523	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
524	    private static final int DAILY_CREATE_LIMIT = 100;
525	
526	    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
527	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
528	
529	    /**
530	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
531	     * Used to enforce the per-city capacity on create (before this owner is saved).
532	     */
533	    private int cityOwnerCount(Owner owner) {
534	        String city = owner.getCity();
535	        int count = 0;
536	        for (Owner existing : this.clinicService.findAllOwners()) {
537	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
538	                count++;
539	            }
540	        }
541	        return count;
542	    }
543	
544	    /** Fixed public holidays the business-day roll skips. */
545	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
546	        java.time.LocalDate.parse("2026-01-01"),
547	        java.time.LocalDate.parse("2026-01-26"),
548	        java.time.LocalDate.parse("2026-04-25"),
549	        java.time.LocalDate.parse("2026-12-25"),
550	        java.time.LocalDate.parse("2026-12-28"));
551	
552	    /**
553	     * Roll a registration date forward onto a business day: any Saturday, Sunday or listed public
554	     * holiday is advanced one day at a time until a non-holiday weekday is reached; a date that is
555	     * already a non-holiday weekday is returned unchanged. Applied to the effective registration date
556	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
557	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
558	     */
559	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
560	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
561	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
562	            || PUBLIC_HOLIDAYS.contains(date)) {
563	            date = date.plusDays(1);
564	        }
565	        return date;
566	    }
567	
568	    /**
569	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
570	     * per-day create limit on create (before this owner is saved).
571	     */
572	    private int ownersRegisteredOn(java.time.LocalDate day) {
573	        int count = 0;
574	        for (Owner existing : this.clinicService.findAllOwners()) {
575	            if (day.equals(existing.getRegistrationDate())) {
576	                count++;
577	            }
578	        }
579	        return count;
580	    }
581	
582	    /**
583	     * The {@code Idempotency-Key} header of the request currently being handled, or {@code null} when
584	     * the header is absent, blank or no servlet request is bound to the calling thread. The generated
585	     * {@link OwnersApi#addOwner} signature carries no header parameter, so it is read from the bound
586	     * request context.
587	     */
588	    private static String currentIdempotencyKey() {
589	        org.springframework.web.context.request.RequestAttributes attrs =
590	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
591	        if (attrs instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttrs) {
592	            String key = servletAttrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
593	            if (key != null && !key.isBlank()) {
594	                return key;
595	            }
596	        }
597	        return null;
598	    }
599	
600	    /**
601	     * The owner's primary identifier, carried by the structured owner-created audit event: the
602	     * unified {@code memberId}.
603	     */
604	    private String primaryIdentifier(Owner owner) {
605	        return owner.getMemberId();
606	    }
607	
608	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
609	    @Override
610	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
611	        HttpHeaders headers = new HttpHeaders();
612	        // Idempotent create: when this request carries an Idempotency-Key we have already seen, return
613	        // the owner originally created for that key (200) instead of creating a duplicate.
614	        String idempotencyKey = currentIdempotencyKey();
615	        if (idempotencyKey != null) {
616	            Integer existingId = idempotentCreates.get(idempotencyKey);
617	            if (existingId != null) {
618	                Owner existing = this.clinicService.findOwnerById(existingId);
619	                if (existing != null) {
620	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
621	                }
622	            }
623	        }
624	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
625	        if (!isPostcodeValid(owner)) {
626	            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
627	                "The postcode is invalid for the owner's city");
628	        }
629	        String telephone = toE164(owner.getTelephone());
630	        if (telephone == null || !hasValidNationalLength(telephone)) {
631	            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
632	                "The telephone number is missing or not a valid number");
633	        }
634	        if (!normalizeEmail(owner)) {
635	            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
636	                "The email address is not valid");
637	        }
638	        String address = composeAddress(owner);
639	        if (address == null) {
640	            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
641	                "The address is missing or incomplete");
642	        }
643	        owner.setAddress(address);
644	        owner.setTelephone(telephone);
645	        if (owner.getRegistrationDate() != null
646	            && owner.getRegistrationDate().isAfter(java.time.LocalDate.now())) {
647	            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
648	                "The registration date cannot be in the future");
649	        }
650	        java.time.LocalDate registrationDate = toBusinessDay(
651	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
652	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
653	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
654	            throw new RestApiRejectionException(HttpStatus.TOO_MANY_REQUESTS,
655	                "The daily owner creation limit has been reached");
656	        }
657	        int cityOwnerCount = cityOwnerCount(owner);
658	        if (cityOwnerCount >= CITY_CAPACITY) {
659	            throw new RestApiRejectionException(HttpStatus.CONFLICT,
660	                "The owner's city has reached its capacity");
661	        }
662	        // The householdId is deterministic (SHA-256 over normalized lastName + '|' + postcode), so
663	        // owners with the same last name and postcode automatically share it. The link is no longer
664	        // created by copying an existing owner's id around.
665	        owner.setHouseholdId(householdIdFor(owner));
666	        List<Owner> householdMembers = householdMembers(owner);
667	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
668	        boolean declaredHouseholdMember = sharesHousehold && !householdMembers.isEmpty();
669	
670	        // Hard duplicate: a new owner whose identityKey (SHA-256 over telephone|email|soundex(lastName))
671	        // equals an existing, non-deleted owner's is the same identity and is always rejected. This is
672	        // now the single duplicate check: because the telephone is part of the key, two owners with the
673	        // same last name and postcode but different telephones no longer collide here and instead fall
674	        // through to the possible-duplicate (soft-match) flagging below.
675	        String identityKey = owner.getIdentityKey();
676	        for (Owner existing : this.clinicService.findAllOwners()) {
677	            if (existing.isDeleted()) {
678	                continue;
679	            }
680	            if (identityKey.equals(existing.getIdentityKey())) {
681	                throw new RestApiRejectionException(HttpStatus.CONFLICT,
682	                    "An owner with the same identity already exists");
683	            }
684	        }
685	        // Household member: another owner already shares this (last name, postcode) household. This
686	        // is no longer rejected as a duplicate — an exact byte-for-byte identity match is already
687	        // caught above, and a distinct additional household member is admitted with its membership
688	        // level capped (see below) at one above the current household maximum. The 'sharesHousehold'
689	        // flag now only signals that the caller vouches for the member, suppressing the
690	        // possible-duplicate flagging below.
691	        // A declared household member is not a suspected duplicate. Otherwise, flag an owner whose
692	        // last name shares an existing owner's soundex and postcode but whose identityKey differs.
693	        if (declaredHouseholdMember) {
694	            owner.setPossibleDuplicate(false);
695	            owner.setPossibleDuplicateOf(null);
696	        }
697	        else {
698	            Owner duplicateOf = possibleDuplicateOf(owner);
699	            owner.setPossibleDuplicate(duplicateOf != null);
700	            owner.setPossibleDuplicateOf(duplicateOf == null ? null : duplicateOf.getId());
701	        }
702	        owner.setNamesakeCount(namesakeCount(owner));
703	        owner.setHouseholdSize(householdMembers.size() + 1);
704	        // Level ceiling: a new owner's membershipLevel cannot exceed one above the current maximum
705	        // membershipLevel among their existing household members. With no existing member, no cap.
706	        if (householdMembers.isEmpty()) {
707	            owner.setMembershipLevelCap(null);
708	        }
709	        else {
710	            int maxHouseholdLevel = householdMembers.stream()
711	                .mapToInt(member -> ownerMapper.membershipLevel(member))
712	                .max()
713	                .getAsInt();
714	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
715	        }
716	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
717	        owner.setCapacityWarning(cityOwnerCount >= CITY_CAPACITY_WARNING_THRESHOLD);
718	        owner.setRegistrationDate(registrationDate);
719	        owner.setMemberId(memberIdFor(owner));
720	        this.clinicService.saveOwner(owner);
721	        if (idempotencyKey != null) {
722	            idempotentCreates.put(idempotencyKey, owner.getId());
723	        }
724	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
725	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
726	            ownerMapper.membershipLevel(owner));
727	        OwnerCreatedEvent event = new OwnerCreatedEvent(2, AUDIT_SEQ.incrementAndGet(), owner.getId(),
728	            primaryIdentifier(owner), ownerMapper.membershipLevel(owner),
729	            ownerMapper.ownerSegment(owner).getValue(), "OWNER_CREATED");
730	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
731	        // Enqueue a welcome notification carrying the owner id and the memberId.
732	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
733	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
734	        headers.setLocation(UriComponentsBuilder.newInstance()
735	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
736	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
737	    }
738	
739	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
740	    @Override
741	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
742	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
743	        if (currentOwner == null) {
744	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
745	        }
746	        currentOwner.setAddress(ownerFieldsDto.getAddress());
747	        currentOwner.setCity(ownerFieldsDto.getCity());
748	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
749	        currentOwner.setLastName(ownerFieldsDto.getLastName());
750	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
751	        currentOwner.setEmail(ownerFieldsDto.getEmail());
752	        if (!normalizeEmail(currentOwner)) {
753	            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
754	                "The email address is not valid");
755	        }
756	        this.clinicService.saveOwner(currentOwner);
757	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
758	    }
759	
760	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
761	    @Transactional
762	    @Override
763	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
764	        Owner owner = this.clinicService.findOwnerById(ownerId);
765	        if (owner == null) {
766	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
767	        }
768	        // Soft-delete: flag the owner deleted and retain the record so it can still be read back.
769	        owner.setDeleted(true);
770	        this.clinicService.saveOwner(owner);
771	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
772	    }
773	
774	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
775	    @Override
776	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
777	        Owner owner = this.clinicService.findOwnerById(ownerId);
778	        if (owner == null) {
779	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
780	        }
781	        HttpHeaders headers = new HttpHeaders();
782	        Pet pet = petMapper.toPet(petFieldsDto);
783	        owner.setId(ownerId);
784	        pet.setOwner(owner);
785	        pet.getType().setName(null);
786	        this.clinicService.savePet(pet);
787	        PetDto petDto = petMapper.toPetDto(pet);
788	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
789	            .buildAndExpand(pet.getId()).toUri());
790	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
791	    }
792	
793	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
794	    @Override
795	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
796	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
797	        if (currentOwner != null) {
798	            Pet currentPet = this.clinicService.findPetById(petId);
799	            if (currentPet != null) {
800	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
801	                currentPet.setName(petFieldsDto.getName());
802	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
803	                this.clinicService.savePet(currentPet);
804	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
805	            }
806	        }
807	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
808	    }
809	
810	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
811	    @Override
812	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
813	        HttpHeaders headers = new HttpHeaders();
814	        Visit visit = visitMapper.toVisit(visitFieldsDto);
815	        Pet pet = new Pet();
816	        pet.setId(petId);
817	        visit.setPet(pet);
818	        this.clinicService.saveVisit(visit);
819	        VisitDto visitDto = visitMapper.toVisitDto(visit);
820	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
821	            .buildAndExpand(visit.getId()).toUri());
822	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
823	    }
824	
825	
826	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
827	    @Override
828	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
829	        Owner owner = this.clinicService.findOwnerById(ownerId);
830	        if (owner != null) {
831	            Pet pet = owner.getPet(petId);
832	            if (pet != null) {
833	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
834	            }
