package org.springframework.samples.petclinic.rest.controller.v1;

import java.util.Collection;
import java.util.List;

import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.mapper.PetMapper;
import org.springframework.samples.petclinic.mapper.VisitMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.model.Pet;
import org.springframework.samples.petclinic.model.Visit;
import org.springframework.samples.petclinic.rest.advice.RestApiRejectionException;
import org.springframework.samples.petclinic.rest.api.OwnersApi;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.PetDto;
import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
import org.springframework.samples.petclinic.rest.dto.VisitDto;
import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
import org.springframework.samples.petclinic.service.ClinicService;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.util.UriComponentsBuilder;

import jakarta.transaction.Transactional;

/**
 * @author Vitaliy Fedoriv
 */

@RestController
@CrossOrigin(exposedHeaders = "errors, content-type")
@RequestMapping("/api")
public class OwnerRestControllerV1 implements OwnersApi {

    /** Dedicated audit trail logger; carries a line for each successful owner create. */
    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");

    /** Notification logger; carries the welcome notification enqueued for each successful create. */
    private static final org.slf4j.Logger NOTIFY = org.slf4j.LoggerFactory.getLogger("NOTIFY");

    /**
     * Process-wide monotonically increasing sequence stamped onto each structured owner-created
     * audit event, so events can be totally ordered across creates.
     */
    private static final java.util.concurrent.atomic.AtomicInteger AUDIT_SEQ =
        new java.util.concurrent.atomic.AtomicInteger(0);

    /** Serializes the immutable structured audit events to JSON. */
    private static final tools.jackson.databind.ObjectMapper AUDIT_MAPPER =
        new tools.jackson.databind.json.JsonMapper();

    /**
     * Immutable structured audit event emitted (as JSON, on the {@code AUDIT} logger) for each
     * successful owner create. {@code schemaVersion} is the audit-event schema version (2 since the
     * version-2 owner identity release), {@code seq} is the process-wide {@link #AUDIT_SEQ} counter,
     * {@code memberId} carries the owner's primary identifier (the version-2 unified memberId) and
     * {@code ownerSegment} carries the owner's marketing segment recomputed from the version-2
     * identity. The component order matches the JSON field order.
     */
    private record OwnerCreatedEvent(int schemaVersion, int seq, Integer ownerId, String memberId,
        Integer membershipLevel, String ownerSegment, String event) {
    }

    /** HTTP header carrying the caller-supplied idempotency key for create requests. */
    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";

    /**
     * Remembers the owner created for each already-seen {@code Idempotency-Key}, so a repeated create
     * with the same key returns the originally created owner instead of creating a duplicate. Keyed by
     * the header value, valued by the created owner's id.
     */
    private final java.util.concurrent.ConcurrentHashMap<String, Integer> idempotentCreates =
        new java.util.concurrent.ConcurrentHashMap<>();

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    private final PetMapper petMapper;

    private final VisitMapper visitMapper;

    public OwnerRestControllerV1(ClinicService clinicService,
                                 OwnerMapper ownerMapper,
                                 PetMapper petMapper,
                                 VisitMapper visitMapper) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
    }

    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
     *  separated by '@', none of which contain whitespace or a second '@'. */
    private static final java.util.regex.Pattern EMAIL_PATTERN =
        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    /** Disposable email domains that are not accepted as an owner's email. */
    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");

    /**
     * Normalize the optional email: absent stays absent; when present it must be syntactically
     * valid and is lower-cased. Returns {@code false} if present but invalid, including when its
     * domain is on the disposable-domain blocklist.
     */
    private boolean normalizeEmail(Owner owner) {
        String email = owner.getEmail();
        if (email == null || email.isEmpty()) {
            owner.setEmail(null);
            return true;
        }
        if (!EMAIL_PATTERN.matcher(email).matches()) {
            return false;
        }
        email = email.toLowerCase(java.util.Locale.ROOT);
        String domain = email.substring(email.indexOf('@') + 1);
        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
            return false;
        }
        owner.setEmail(email);
        return true;
    }

    /**
     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
     *
     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
     *         a valid E.164 number.
     */
    private static String toE164(String raw) {
        if (raw == null) {
            return null;
        }
        String cleaned = raw.replaceAll("[\\s\\-()]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            digits = cleaned.substring(1);
        } else {
            if (cleaned.startsWith("0")) {
                cleaned = cleaned.substring(1);
            }
            digits = "61" + cleaned;
        }
        if (!digits.matches("\\d{8,15}")) {
            return null;
        }
        return "+" + digits;
    }

    /**
     * Validate the national-number length of a canonical E.164 string against its country code:
     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Numbers carrying any
     * other country code are not length-checked here and are accepted. Expects the '+'-prefixed digit
     * string produced by {@link #toE164}.
     *
     * @return {@code true} when the national-number length is correct for the country code.
     */
    private static boolean hasValidNationalLength(String e164) {
        String digits = e164.substring(1);
        if (digits.startsWith("61")) {
            return digits.length() - 2 == 9;
        }
        if (digits.startsWith("1")) {
            return digits.length() - 1 == 10;
        }
        return true;
    }

    /**
     * The version-2 region code embedded inside the identifiers: the fixed {@code 'V2'} version tag
     * mixed with the region code derived from the owner's postcode (NSW/VIC/QLD, or {@code UNKNOWN}
     * when the postcode is absent or in no known range), e.g. {@code V2NSW} or {@code V2UNKNOWN}.
     * Because it always carries the {@code 'V2'} prefix it never equals a version-1 (plain) region,
     * so every identifier derived from it changes and no version-1 value is produced again. This is
     * only the region code used <em>inside</em> the identifiers; the user-facing {@code locality},
     * {@code timezone} and owner-segment region stay the plain region code (see {@link OwnerMapper}).
     */
    private String identityRegion(Owner owner) {
        String region = ownerMapper.regionFromPostcode(owner);
        if (region == null) {
            region = "UNKNOWN";
        }
        return Owner.IDENTITY_VERSION_TAG + region;
    }

    /**
     * Build the unified member id {@code <REGION><FY><HASH8><CHK>}: REGION is the version-2 region
     * code ({@link #identityRegion(Owner)} — the {@code 'V2'} tag mixed with the postcode-derived
     * region, e.g. {@code V2NSW} or {@code V2UNKNOWN}); FY is the two-digit fiscal year of the owner's
     * (business-day-adjusted) registrationDate; HASH8 is the first 8 upper-case hex characters of
     * SHA-256 over the concatenation of the owner's normalized (E.164) telephone and last name; and
     * CHK is a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>} (e.g.
     * {@code V2NSW273F9A0C177}). No sequence numbers are used, so the base id is a pure function of
     * the owner's region, fiscal year and region-and-hash identity. When that base id collides with an
     * existing owner's memberId, {@code -<n>} is appended with the smallest {@code n} of 2 or more that
     * makes it unique, returning the de-duplicated id.
     */
    private String memberIdFor(Owner owner) {
        String region = identityRegion(owner);
        String fy = String.format("%02d", ownerMapper.fiscalYearOf(owner.getRegistrationDate()) % 100);
        String core = region + fy + hash8(owner.getTelephone(), owner.getLastName());
        String base = core + luhn(core);

        java.util.Set<String> existingIds = new java.util.HashSet<>();
        for (Owner existing : this.clinicService.findAllOwners()) {
            String id = existing.getMemberId();
            if (id != null) {
                existingIds.add(id);
            }
        }
        if (!existingIds.contains(base)) {
            return base;
        }
        for (int n = 2; ; n++) {
            String candidate = base + "-" + n;
            if (!existingIds.contains(candidate)) {
                return candidate;
            }
        }
    }

    /**
     * A single Luhn check digit (0-9) over the digits contained in {@code value}; non-digit characters
     * are ignored.
     */
    private static int luhn(String value) {
        int sum = 0;
        boolean dbl = true;
        for (int i = value.length() - 1; i >= 0; i--) {
            char c = value.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    /**
     * First 8 upper-case hex characters (the first 4 bytes) of SHA-256 over
     * {@code normalizedTelephone + lastName}, treating a {@code null} component as empty.
     */
    private static String hash8(String normalizedTelephone, String lastName) {
        String input = (normalizedTelephone == null ? "" : normalizedTelephone)
            + (lastName == null ? "" : lastName);
        try {
            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(8);
            for (int i = 0; i < 4; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (java.security.NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    /** Common street-type abbreviations expanded during address normalization. */
    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");

    /**
     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
     */
    private static String normalizeAddress(String value) {
        if (value == null) {
            return "";
        }
        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
        }
        return sb.toString();
    }

    /**
     * Resolve and normalize the owner's postal address, preferring the structured form.
     *
     * <p>When a non-blank {@code addressLine1} is supplied the structured form is used: it, and the
     * optional {@code addressLine2}, are normalized in place and the composed address is the
     * normalized addressLine1 with a single space and the normalized addressLine2 appended when
     * addressLine2 is present. Otherwise the flat {@code address} input is normalized. Returns
     * {@code null} when neither form yields a non-empty address, so the caller can reject the
     * request.
     */
    private String composeAddress(Owner owner) {
        String line1 = owner.getAddressLine1();
        if (line1 != null && !line1.isBlank()) {
            String normalizedLine1 = normalizeAddress(line1);
            owner.setAddressLine1(normalizedLine1);
            String line2 = owner.getAddressLine2();
            if (line2 != null && !line2.isBlank()) {
                String normalizedLine2 = normalizeAddress(line2);
                owner.setAddressLine2(normalizedLine2);
                return normalizedLine1 + " " + normalizedLine2;
            }
            owner.setAddressLine2(null);
            return normalizedLine1.isEmpty() ? null : normalizedLine1;
        }
        String normalized = normalizeAddress(owner.getAddress());
        return normalized.isEmpty() ? null : normalized;
    }

    /**
     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
     */
    private static String normalizeForHousehold(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
    }

    /**
     * Return the owners that already share this owner's household, i.e. resolve to the same
     * deterministic {@link #householdIdFor(Owner) householdId} (same normalized last name and
     * postcode).
     */
    private List<Owner> householdMembers(Owner owner) {
        String householdId = householdIdFor(owner);
        List<Owner> members = new java.util.ArrayList<>();
        for (Owner existing : this.clinicService.findAllOwners()) {
            if (existing.isDeleted()) {
                continue;
            }
            if (householdId.equals(householdIdFor(existing))) {
                members.add(existing);
            }
        }
        return members;
    }

    /**
     * Return {@code true} when another owner already shares this owner's household, i.e. resolves to
     * the same deterministic {@link #householdIdFor(Owner) householdId}.
     */
    private boolean sharesHouseholdWithExisting(Owner owner) {
        return !householdMembers(owner).isEmpty();
    }

    /**
     * Count the existing owners that share this owner's first name and last name, compared
     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
     */
    private int namesakeCount(Owner owner) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        int count = 0;
        for (Owner existing : this.clinicService.findAllOwners()) {
            if (firstName != null && lastName != null
                && firstName.equalsIgnoreCase(existing.getFirstName())
                && lastName.equalsIgnoreCase(existing.getLastName())) {
                count++;
            }
        }
        return count;
    }

    /**
     * A stable, shared household identifier: the first 12 hex characters of SHA-256 over
     * {@code 'V2' + '|' + normalizedLastName + '|' + postcode} (an absent postcode contributes an
     * empty string). The leading {@code 'V2'} version tag is mixed in so the version-2 value never
     * equals the version-1 value, yet the id stays a pure function of the last name and postcode, so
     * every owner in the same household still deterministically resolves to the same value.
     */
    private static String householdIdFor(Owner owner) {
        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
        String key = Owner.IDENTITY_VERSION_TAG + "|" + normalizeForHousehold(owner.getLastName()) + "|" + postcode;
        try {
            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(12);
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (java.security.NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
        "NSW", new int[] {2000, 2099},
        "VIC", new int[] {3000, 3099},
        "QLD", new int[] {4000, 4099});

    /**
     * Validate the optional postcode. Absent (null/empty) is valid — postcode is optional. When
     * present it must be exactly 4 digits; and when the owner's city maps to a known region (via the
     * mapper's fixed city-to-region table) it must fall inside that region's inclusive range
     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
     * postcode.
     */
    private boolean isPostcodeValid(Owner owner) {
        String postcode = owner.getPostcode();
        if (postcode == null || postcode.isEmpty()) {
            return true;
        }
        if (!postcode.matches("\\d{4}")) {
            return false;
        }
        int[] range = REGION_POSTCODE_RANGES.get(ownerMapper.cityRegion(owner));
        if (range == null) {
            return true;
        }
        int value = Integer.parseInt(postcode);
        return value >= range[0] && value <= range[1];
    }

    /**
     * Find an existing owner that makes this (already known to be non-hard-duplicate) owner a
     * "possible duplicate": one whose last name shares this owner's {@link Owner#soundex(String)
     * soundex} and whose postcode matches, yet whose whole {@link Owner#getIdentityKey() identityKey}
     * differs (so it is not a hard duplicate). When several match, the one with the smallest id is
     * chosen so the result is deterministic. Returns {@code null} when the owner has no postcode or no
     * such existing owner exists.
     */
    private Owner possibleDuplicateOf(Owner owner) {
        String lastName = owner.getLastName();
        String postcode = owner.getPostcode();
        if (lastName == null || postcode == null || postcode.isEmpty()) {
            return null;
        }
        String soundex = Owner.soundex(lastName);
        String identityKey = owner.getIdentityKey();
        Owner match = null;
        for (Owner existing : this.clinicService.findAllOwners()) {
            if (soundex.equals(Owner.soundex(existing.getLastName()))
                && postcode.equals(existing.getPostcode())
                && !identityKey.equals(existing.getIdentityKey())) {
                if (match == null || (existing.getId() != null && match.getId() != null
                    && existing.getId() < match.getId())) {
                    match = existing;
                }
            }
        }
        return match;
    }

    /** Maximum number of owners permitted in a single city. */
    private static final int CITY_CAPACITY = 50;

    /**
     * Number of owners already in a city at or beyond which a capacity warning is flagged (the city
     * is approaching the {@link #CITY_CAPACITY} hard limit). A city holding 40-49 owners warns.
     */
    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;

    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
    private static final int DAILY_CREATE_LIMIT = 100;

    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;

    /**
     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
     * Used to enforce the per-city capacity on create (before this owner is saved).
     */
    private int cityOwnerCount(Owner owner) {
        String city = owner.getCity();
        int count = 0;
        for (Owner existing : this.clinicService.findAllOwners()) {
            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
                count++;
            }
        }
        return count;
    }

    /** Fixed public holidays the business-day roll skips. */
    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
        java.time.LocalDate.parse("2026-01-01"),
        java.time.LocalDate.parse("2026-01-26"),
        java.time.LocalDate.parse("2026-04-25"),
        java.time.LocalDate.parse("2026-12-25"),
        java.time.LocalDate.parse("2026-12-28"));

    /**
     * Roll a registration date forward onto a business day: any Saturday, Sunday or listed public
     * holiday is advanced one day at a time until a non-holiday weekday is reached; a date that is
     * already a non-holiday weekday is returned unchanged. Applied to the effective registration date
     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
     * the membership number's year segment and the per-day create limit — uses the adjusted date.
     */
    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
            || PUBLIC_HOLIDAYS.contains(date)) {
            date = date.plusDays(1);
        }
        return date;
    }

    /**
     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
     * per-day create limit on create (before this owner is saved).
     */
    private int ownersRegisteredOn(java.time.LocalDate day) {
        int count = 0;
        for (Owner existing : this.clinicService.findAllOwners()) {
            if (day.equals(existing.getRegistrationDate())) {
                count++;
            }
        }
        return count;
    }

    /**
     * The {@code Idempotency-Key} header of the request currently being handled, or {@code null} when
     * the header is absent, blank or no servlet request is bound to the calling thread. The generated
     * {@link OwnersApi#addOwner} signature carries no header parameter, so it is read from the bound
     * request context.
     */
    private static String currentIdempotencyKey() {
        org.springframework.web.context.request.RequestAttributes attrs =
            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
        if (attrs instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttrs) {
            String key = servletAttrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
            if (key != null && !key.isBlank()) {
                return key;
            }
        }
        return null;
    }

    /**
     * The owner's primary identifier, carried by the structured owner-created audit event: the
     * unified {@code memberId}.
     */
    private String primaryIdentifier(Owner owner) {
        return owner.getMemberId();
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        // Idempotent create: when this request carries an Idempotency-Key we have already seen, return
        // the owner originally created for that key (200) instead of creating a duplicate.
        String idempotencyKey = currentIdempotencyKey();
        if (idempotencyKey != null) {
            Integer existingId = idempotentCreates.get(idempotencyKey);
            if (existingId != null) {
                Owner existing = this.clinicService.findOwnerById(existingId);
                if (existing != null) {
                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
                }
            }
        }
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        if (!isPostcodeValid(owner)) {
            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
                "The postcode is invalid for the owner's city");
        }
        String telephone = toE164(owner.getTelephone());
        if (telephone == null || !hasValidNationalLength(telephone)) {
            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
                "The telephone number is missing or not a valid number");
        }
        if (!normalizeEmail(owner)) {
            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
                "The email address is not valid");
        }
        String address = composeAddress(owner);
        if (address == null) {
            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
                "The address is missing or incomplete");
        }
        owner.setAddress(address);
        owner.setTelephone(telephone);
        if (owner.getRegistrationDate() != null
            && owner.getRegistrationDate().isAfter(java.time.LocalDate.now())) {
            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
                "The registration date cannot be in the future");
        }
        java.time.LocalDate registrationDate = toBusinessDay(
            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
            throw new RestApiRejectionException(HttpStatus.TOO_MANY_REQUESTS,
                "The daily owner creation limit has been reached");
        }
        int cityOwnerCount = cityOwnerCount(owner);
        if (cityOwnerCount >= CITY_CAPACITY) {
            throw new RestApiRejectionException(HttpStatus.CONFLICT,
                "The owner's city has reached its capacity");
        }
        // The householdId is deterministic (SHA-256 over normalized lastName + '|' + postcode), so
        // owners with the same last name and postcode automatically share it. The link is no longer
        // created by copying an existing owner's id around.
        owner.setHouseholdId(householdIdFor(owner));
        List<Owner> householdMembers = householdMembers(owner);
        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
        boolean declaredHouseholdMember = sharesHousehold && !householdMembers.isEmpty();

        // Hard duplicate: a new owner whose identityKey (SHA-256 over telephone|email|soundex(lastName))
        // equals an existing, non-deleted owner's is the same identity and is always rejected. This is
        // now the single duplicate check: because the telephone is part of the key, two owners with the
        // same last name and postcode but different telephones no longer collide here and instead fall
        // through to the possible-duplicate (soft-match) flagging below.
        String identityKey = owner.getIdentityKey();
        for (Owner existing : this.clinicService.findAllOwners()) {
            if (existing.isDeleted()) {
                continue;
            }
            if (identityKey.equals(existing.getIdentityKey())) {
                throw new RestApiRejectionException(HttpStatus.CONFLICT,
                    "An owner with the same identity already exists");
            }
        }
        // Household member: another owner already shares this (last name, postcode) household. This
        // is no longer rejected as a duplicate — an exact byte-for-byte identity match is already
        // caught above, and a distinct additional household member is admitted with its membership
        // level capped (see below) at one above the current household maximum. The 'sharesHousehold'
        // flag now only signals that the caller vouches for the member, suppressing the
        // possible-duplicate flagging below.
        // A declared household member is not a suspected duplicate. Otherwise, flag an owner whose
        // last name shares an existing owner's soundex and postcode but whose identityKey differs.
        if (declaredHouseholdMember) {
            owner.setPossibleDuplicate(false);
            owner.setPossibleDuplicateOf(null);
        }
        else {
            Owner duplicateOf = possibleDuplicateOf(owner);
            owner.setPossibleDuplicate(duplicateOf != null);
            owner.setPossibleDuplicateOf(duplicateOf == null ? null : duplicateOf.getId());
        }
        owner.setNamesakeCount(namesakeCount(owner));
        owner.setHouseholdSize(householdMembers.size() + 1);
        // Level ceiling: a new owner's membershipLevel cannot exceed one above the current maximum
        // membershipLevel among their existing household members. With no existing member, no cap.
        if (householdMembers.isEmpty()) {
            owner.setMembershipLevelCap(null);
        }
        else {
            int maxHouseholdLevel = householdMembers.stream()
                .mapToInt(member -> ownerMapper.membershipLevel(member))
                .max()
                .getAsInt();
            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
        }
        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
        owner.setCapacityWarning(cityOwnerCount >= CITY_CAPACITY_WARNING_THRESHOLD);
        owner.setRegistrationDate(registrationDate);
        owner.setMemberId(memberIdFor(owner));
        this.clinicService.saveOwner(owner);
        if (idempotencyKey != null) {
            idempotentCreates.put(idempotencyKey, owner.getId());
        }
        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
            ownerMapper.membershipLevel(owner));
        OwnerCreatedEvent event = new OwnerCreatedEvent(2, AUDIT_SEQ.incrementAndGet(), owner.getId(),
            primaryIdentifier(owner), ownerMapper.membershipLevel(owner),
            ownerMapper.ownerSegment(owner).getValue(), "OWNER_CREATED");
        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
        // Enqueue a welcome notification carrying the owner id and the memberId.
        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        currentOwner.setAddress(ownerFieldsDto.getAddress());
        currentOwner.setCity(ownerFieldsDto.getCity());
        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
        currentOwner.setLastName(ownerFieldsDto.getLastName());
        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
        currentOwner.setEmail(ownerFieldsDto.getEmail());
        if (!normalizeEmail(currentOwner)) {
            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
                "The email address is not valid");
        }
        this.clinicService.saveOwner(currentOwner);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        // Soft-delete: flag the owner deleted and retain the record so it can still be read back.
        owner.setDeleted(true);
        this.clinicService.saveOwner(owner);
        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        HttpHeaders headers = new HttpHeaders();
        Pet pet = petMapper.toPet(petFieldsDto);
        owner.setId(ownerId);
        pet.setOwner(owner);
        pet.getType().setName(null);
        this.clinicService.savePet(pet);
        PetDto petDto = petMapper.toPetDto(pet);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
            .buildAndExpand(pet.getId()).toUri());
        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner != null) {
            Pet currentPet = this.clinicService.findPetById(petId);
            if (currentPet != null) {
                currentPet.setBirthDate(petFieldsDto.getBirthDate());
                currentPet.setName(petFieldsDto.getName());
                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
                this.clinicService.savePet(currentPet);
                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Visit visit = visitMapper.toVisit(visitFieldsDto);
        Pet pet = new Pet();
        pet.setId(petId);
        visit.setPet(pet);
        this.clinicService.saveVisit(visit);
        VisitDto visitDto = visitMapper.toVisitDto(visit);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
            .buildAndExpand(visit.getId()).toUri());
        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
    }


    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner != null) {
            Pet pet = owner.getPet(petId);
            if (pet != null) {
                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }
